import {spinnerPresets, spinnerLessons, spinnerQuestions, spinnerCopy} from './spinner-table-content.mjs';
import {changeSpinnerTable, spinnerTableModel, spinnerTableNarration, spinnerSlotMark, spinnerSlotAngle, browserSpinnerSlot} from './spinner-table-core.mjs';
import {chancePoint} from './chance-line-core.mjs';
import {hearButton} from './play-media.mjs';

const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names=['Sun','Cloud','Rain'];
const pages=[['design','Design the wheel'],['runs','Try runs'],['learn','See why']];
const button=(action,label,value='',extra='')=>`<button type="button" class="secondary" data-stw-action="${action}" data-stw-value="${esc(value)}" ${extra}>${esc(label)}</button>`;
const icon=(i)=>i===0?'<circle cx="0" cy="0" r="6"/><path d="M0-11V-8M0 8V11M-11 0H-8M8 0H11M-8-8L-6-6M6 6L8 8M-8 8L-6 6M6-6L8-8"/>':i===1?'<path d="M-10 4C-16 3-13-6-7-5C-7-14 7-14 8-5C17-6 18 5 11 6H-8Z"/>':'<path d="M0-12C-3-6-10 1-8 6C-5 14 7 13 9 5C10 0 3-7 0-12Z"/>';
const point=(angle,r)=>[150+Math.sin(angle*Math.PI/180)*r,150-Math.cos(angle*Math.PI/180)*r];
function wheel(counts,label,last=null){
 const slices=Array.from({length:12},(_,slot)=>{const a=point(slot*30,130),b=point((slot+1)*30,130),p=point(spinnerSlotAngle(slot),99),i=spinnerSlotMark(counts,slot);return `<g data-stw-slice="${slot}" data-stw-mark="${i}" class="stw-slice stw-mark-${i}${last?.slot===slot?' stw-selected':''}"><path d="M150 150L${a.join(' ')}A130 130 0 0 1 ${b.join(' ')}Z"/><g class="stw-symbol" transform="translate(${p.join(' ')})">${icon(i)}</g></g>`;}).join('');
 let start=1;const key=counts.map((count,i)=>{const range=count?`${start}${count===1?'':`–${start+count-1}`}`:'none';start+=count;return `<li><span class="stw-key-symbol stw-mark-${i}" aria-hidden="true"><svg viewBox="-18 -18 36 36">${icon(i)}</svg></span><span><strong>${names[i]}: ${count} ${count===1?'stop':'stops'}</strong><br>Stop numbers: ${range}<br>Model chance: ${chancePoint(count)}</span></li>`;}).join('');
 return `<figure class="stw-wheel-picture"><figcaption><strong>${esc(label)}</strong></figcaption><svg class="stw-wheel" data-stw-wheel viewBox="0 0 300 300" role="img" aria-label="${esc(label)}: 12 equal stops. ${counts.map((c,i)=>`${c} ${names[i]}`).join(', ')}. Stops numbered clockwise from the top.">${slices}<circle cx="150" cy="150" r="13" class="stw-hub"/>${last?`<g class="stw-pointer" data-stw-pointer data-slot="${last.slot}" data-angle="${last.angle}" style="transform:rotate(${last.angle}deg)"><path d="M145 150L150 24L155 150Z"/><circle cx="150" cy="150" r="8"/></g>`:''}</svg><p class="stw-wheel-note">12 equal slices · stops 1–12 clockwise from the top</p><ul class="stw-key">${key}</ul></figure>`;
}
const rule=()=>`<p class="stw-rule">${esc(spinnerCopy.rule)}</p>`;
function startButton(m){return button('start','Start a run with this wheel','',`id="stw-start" ${m.canStart?'':'disabled'}`);}
function design(work,m){return `<div class="stw-bench">${wheel(work.counts,'Current design')}<section class="stw-controls" aria-label="Change the wheel"><p>Move one of the twelve slices to another picture mark.</p><label for="stw-from">Take one slice from</label><select id="stw-from" data-stw-action="from">${names.map((n,i)=>`<option value="${i}"${work.from===i?' selected':''}>${n}</option>`).join('')}</select><label for="stw-to">Give it to</label><select id="stw-to" data-stw-action="to">${names.map((n,i)=>`<option value="${i}"${work.to===i?' selected':''}>${n}</option>`).join('')}</select>${button('move','Move one slice','',m.canMove?'':'disabled')}${m.moveReason?`<p class="stw-reason">${esc(m.moveReason)}</p>`:''}<h3>Try a design</h3><div class="stw-presets">${spinnerPresets.map((p,i)=>button('preset',p.label??p.name,i)).join('')}</div><p><strong>${m.design.equal?'Equal chance for all three marks':'The named marks have unequal chances'}</strong></p><p>${work.counts.map(n=>`${n}/12`).join(' + ')} = 12/12 = 1</p>${startButton(m)}${!m.canStart?'<p>Three runs are here. On Try runs, begin a fresh set to use another wheel.</p>':''}</section></div>${rule()}`;}
function resetControls(work){if(!work.runs.length)return '';if(!work.confirmReset)return `<div class="stw-reset">${button('reset-request','Begin a fresh set')}</div>`;return `<div class="stw-reset">${button('reset-cancel','Keep these runs','', 'id="stw-keep"')}<div class="stw-confirm"><p>This clears ${work.runs.length===1?'this 1 run':`these ${work.runs.length} runs`} from this visit. It does not change your saved Seed Stall experiments.</p>${button('reset-confirm','Clear these local runs')}</div></div>`;}
function tally(active){return `<section class="stw-tally" data-stw-tally aria-label="Recorded screen draws"><h3>Recorded screen draws</h3><p>Integer counts · fixed scale 0–20</p>${names.map((n,i)=>`<div class="stw-tally-row" data-stw-tally-mark="${i}" data-count="${active.tally[i]}"><span>${n} <strong>${active.tally[i]}</strong></span><div class="stw-tally-track" aria-hidden="true"><span class="stw-mark-${i}" style="width:${active.tally[i]*5}%"></span></div></div>`).join('')}<div class="stw-count-scale" aria-hidden="true"><span>0</span><span>5</span><span>10</span><span>15</span><span>20</span></div></section>`;}
function runs(work,m){const a=m.active;return `${work.runs.length?`<nav class="stw-actions stw-run-tabs" aria-label="Choose a run">${work.runs.map((r,i)=>button('active',`Run ${i+1} · ${r.draws.length} draws`,i,`aria-pressed="${work.active===i}"`)).join('')}</nav>`:''}<h3 id="stw-run-title" tabindex="-1">${a?`Run ${a.number}`:'Try your current design'}</h3><div class="stw-bench">${wheel(a?a.counts:work.counts,a?`Run ${a.number}'s wheel`:'Current design',a?.last)}<section class="stw-controls" aria-label="Run controls">${a?`${a.last?`<h3 id="stw-result" tabindex="-1">Screen draw ${a.drawCount}: ${a.last.mark.label} mark. Tally: Sun ${a.tally[0]}, Cloud ${a.tally[1]}, Rain ${a.tally[2]}.</h3>`:'<h3 id="stw-result" tabindex="-1">Not drawn yet</h3>'}${button('spin','Spin','',a.canSpin?'':'disabled')}${!a.canSpin?'<p>This run has 20 screen draws. Keep it to compare.</p>':''}${a.drawCount?tally(a):''}${a.mismatch?`<p class="stw-rule" data-stw-mismatch>This run uses its earlier wheel. ${m.canStart?'Start another run':'Begin a fresh set'} to use your current design.</p>`:''}`:'<p>Not drawn yet</p>'}${m.notice?`<p id="stw-status" class="stw-feedback" tabindex="-1" role="status">${esc(m.notice)}</p>`:''}<div class="stw-new-run">${startButton(m)}</div>${resetControls(work)}</section></div>${a?`<section class="stw-results"><h3>Run ${a.number}'s ordered results</h3><ol data-stw-results>${Array.from({length:20},(_,i)=>`<li class="${a.results[i]?'stw-drawn':'stw-undrawn'}">${i+1}. ${a.results[i]?`${a.results[i].mark.label} mark`:'Not drawn'}</li>`).join('')}</ol></section>`:''}${work.runs.length?`<section class="stw-summary">${button('summary',work.summaryOpen?'Fold run comparison':'Compare these runs','',`aria-expanded="${work.summaryOpen}"`)}${work.summaryOpen?`<div class="stw-summary-rows" data-stw-summary>${m.summary.map(r=>`<article><h3>Run ${r.number}</h3><p>Frozen stops: ${r.counts.map((c,i)=>`${names[i]} ${c}`).join(', ')}.</p><p>Recorded screen draws: ${r.drawCount?r.tally.map((c,i)=>`${names[i]} ${c}`).join(', '):'Not drawn yet'}.</p></article>`).join('')}</div>`:''}</section>`:''}${rule()}`;}
const turns=(action,index,noun)=>`<nav class="stw-actions stw-turns" aria-label="${noun} navigation">${button(action,`Previous ${noun}`,index-1,`data-stw-turn="previous" ${index===0?'disabled':''}`)}<span>${index+1} of 4</span>${button(action,`Next ${noun}`,index+1,`data-stw-turn="next" ${index===3?'disabled':''}`)}</nav>`;
function lesson(work){const l=spinnerLessons[work.lesson];const pictures=work.lesson===1||work.lesson===3?[[6,3,3],[4,4,4]]:[[6,3,3]];if(work.lesson===1)pictures.reverse();return `${turns('lesson',work.lesson,'picture')}<h3 id="stw-lesson" tabindex="-1">${esc(l.title)}</h3><p class="stw-teaching">${esc(l.text)}</p>${work.lesson===2?'<p class="stw-example"><strong>An example, not your run and not a fresh random draw</strong><br>Sun → Sun → Sun → Cloud</p>':''}<div class="stw-lesson-wheels">${pictures.map((c,i)=>wheel(c,work.lesson===3?(i===0?"Earlier run’s frozen wheel":'Separately edited design'):'Pictured wheel')).join('')}</div>`;}
function questions(work,m){const q=spinnerQuestions[work.question];return `${turns('question',work.question,'question')}<h3 id="stw-question" tabindex="-1">${esc(q.prompt)}</h3><div class="stw-choices">${q.choices.map((c,i)=>button('answer',c.label,i,`aria-pressed="${m.selected===i}"`)).join('')}</div>${m.feedback?`<p class="stw-feedback" role="status" data-stw-feedback>${esc(m.feedback)}</p>`:''}${button('explanation',m.explanation?'Hide explanation':'Show explanation','',`aria-expanded="${!!m.explanation}"`)}${m.explanation?`<p class="stw-feedback" data-stw-explanation>${esc(m.explanation)}</p>`:''}`;}
function learn(work,m){return `<nav class="stw-actions" aria-label="See why panels">${button('learn-panel','Teaching pictures','pictures',`aria-pressed="${work.learnPanel==='pictures'}"`)}${button('learn-panel','Try questions','questions',`aria-pressed="${work.learnPanel==='questions'}"`)}</nav><h3 id="stw-panel-title" tabindex="-1">${work.learnPanel==='pictures'?'Teaching pictures':'Supported questions'}</h3>${work.learnPanel==='pictures'?lesson(work):questions(work,m)}`;}
export function spinnerTablePage(work){const m=spinnerTableModel(work);return `<div class="stw-page" data-stw-root><header><div class="stw-actions">${button('back','Back to Seed Stall')}${hearButton(spinnerTableNarration(work),'Hear this panel').replace('data-speak=','data-stw-hear data-speak=')}</div><h1 id="stw-title" tabindex="-1">Spinner Table</h1><p>Help Nuria redesign the orchard’s picture sign.</p></header><nav class="stw-pages" aria-label="Spinner Table pages">${pages.map(([p,t])=>button('page',t,p,`aria-current="${p===work.page?'page':'false'}"`)).join('')}</nav><section class="stw-sheet"><h2 id="stw-page-title" tabindex="-1">${pages.find(([p])=>p===work.page)[1]}</h2>${work.page==='design'?design(work,m):work.page==='runs'?runs(work,m):learn(work,m)}</section><p class="stw-lifetime">${esc(spinnerCopy.lifetime)}</p></div>`;}

export function bindSpinnerTable(work,ctx){
 const root=document.querySelector('[data-stw-root]');if(!root)return;
 const valid=(n,e)=>{if(ctx.live(n)&&!n.disabled)return true;e.preventDefault();e.stopImmediatePropagation();return false;};
 const selector=n=>`[data-stw-action="${n.dataset.stwAction}"][data-stw-value="${CSS.escape(n.dataset.stwValue??'')}"]`;
 const act=(n,e)=>{
  if(!valid(n,e))return;
  const action=n.dataset.stwAction;
  if(['reset-cancel','reset-confirm'].includes(action)&&e.detail>1){e.preventDefault();e.stopImmediatePropagation();return;}
  if(n.matches('[data-stw-hear]')){ctx.stopSpeech?.();ctx.stopSound?.();n.dataset.speak=spinnerTableNarration(work);return;}
  e.preventDefault();
  if(action==='back'){ctx.stopSpeech?.();ctx.stopSound?.();const closed=changeSpinnerTable(work,'reset-cancel');if(closed!==work)ctx.change(closed);ctx.back();return;}
  let value=n.matches('select')?Number(n.value):n.dataset.stwValue;
  if(['from','to','preset','active','lesson','question','answer'].includes(action))value=Number(value);
  let resolved=action,slot=null;
  if(action==='spin'){
   if(!spinnerTableModel(work).active?.canSpin)return;
   slot=browserSpinnerSlot();resolved=slot===null?'entropy-failure':'spin';value=slot;
  }
  const next=changeSpinnerTable(work,resolved,value);
  if(next===work&&resolved!=='entropy-failure')return;
  ctx.stopSpeech?.();ctx.stopSound?.();ctx.change(next);ctx.render();
  const nextModel=spinnerTableModel(next);
  let focus=action==='page'?'#stw-page-title':action==='learn-panel'?'#stw-panel-title':action==='lesson'?'#stw-lesson':action==='question'?'#stw-question':action==='from'?'#stw-from':action==='to'?'#stw-to':action==='move'?(nextModel.canMove?'[data-stw-action="move"]':'#stw-from'):['start','active'].includes(action)?'#stw-run-title':resolved==='entropy-failure'?'#stw-status':action==='spin'?'#stw-result':action==='reset-request'?'#stw-keep':action==='reset-cancel'?'[data-stw-action="reset-request"]':action==='reset-confirm'?'#stw-start':selector(n);
  if(['lesson','question'].includes(action)&&n.dataset.stwTurn){const same=`[data-stw-action="${action}"][data-stw-turn="${n.dataset.stwTurn}"]:not(:disabled)`;if(!document.querySelector(same))focus=action==='lesson'?'#stw-lesson':'#stw-question';}
  ctx.focus?.(focus);
  if(action==='spin'&&slot!==null){const pointer=document.querySelector('[data-stw-root] [data-stw-pointer]');if(pointer&&typeof pointer.animate==='function'&&!globalThis.matchMedia?.('(prefers-reduced-motion: reduce)').matches){const angle=spinnerSlotAngle(slot);pointer.animate([{transform:`rotate(${angle-720}deg)`},{transform:`rotate(${angle}deg)`}],{duration:500,easing:'ease-out'});}}
 };
 root.addEventListener('keydown',e=>{if(e.repeat&&e.target.closest('[data-stw-action="spin"],[data-stw-action="reset-confirm"],[data-stw-action="reset-cancel"]')){e.preventDefault();e.stopImmediatePropagation();}},{capture:true});
 root.querySelectorAll('button,select').forEach(n=>{n.addEventListener('click',e=>{if(n.matches('select')){valid(n,e);return;}act(n,e);},{capture:true});if(n.matches('select'))n.addEventListener('change',e=>act(n,e),{capture:true});});
}
